import{_ as e,c as a,a2 as s,o as t}from"./chunks/framework.CoXjB5sU.js";const k=JSON.parse('{"title":"Purchase a certificate from a Certification Authority (CA)","description":"","frontmatter":{"prev":{"text":"Use a certificate you already own","link":"/doc/guides/other-operations/replace-https-certificate/with-existing-certificate"},"next":{"text":"Validate the domain ownership","link":"/doc/guides/other-operations/replace-https-certificate/validate-domain-owner"}},"headers":[],"relativePath":"doc/guides/other-operations/replace-https-certificate/purchase-new-ca-certificate.md","filePath":"doc/guides/other-operations/replace-https-certificate/purchase-new-ca-certificate.md"}'),n={name:"doc/guides/other-operations/replace-https-certificate/purchase-new-ca-certificate.md"};function h(r,i,c,l,p,o){return t(),a("div",null,i[0]||(i[0]=[s(`<h1 id="purchase-a-certificate-from-a-certification-authority-ca" tabindex="-1">Purchase a certificate from a Certification Authority (CA) <a class="header-anchor" href="#purchase-a-certificate-from-a-certification-authority-ca" aria-label="Permalink to &quot;Purchase a certificate from a Certification Authority (CA)&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If your server is reachable from the Internet, <a href="https://letsencrypt.org" target="_blank" rel="noreferrer">Let&#39;s Encrypt</a> gives free certificates that the proxy renews automatically: <code>BASE_PATH/bin/replace-certificate.sh acme &lt;contact email&gt;</code>. Ask your institution too: many of them issue certificates to their own servers.</p></div><h2 id="certificate-request-csr-generation" tabindex="-1">Certificate request (CSR) generation <a class="header-anchor" href="#certificate-request-csr-generation" aria-label="Permalink to &quot;Certificate request (CSR) generation&quot;">​</a></h2><p>The CA issues the certificate from a certificate signing request (CSR), generated with a new private key. Generate both on the ioChem-BD server, replacing the hostname with yours:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iochembd$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/certificate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/certificate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iochembd$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> req</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -newkey</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa:2048</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -nodes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -keyout</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iochembd.university.edu.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">              -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iochembd.university.edu.csr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">              -subj</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;/CN=iochembd.university.edu&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">              -addext</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;subjectAltName=DNS:iochembd.university.edu&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iochembd$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iochembd.university.edu.key</span></span></code></pre></div><p>Keep the <em>.key</em> file private: never send it to the CA. Some CAs ask for the organization details of the request in their own form; others read them from the CSR, which you can add to <code>-subj</code>, for example <code>&quot;/C=ES/ST=Catalonia/L=Tarragona/O=University of Example/CN=iochembd.university.edu&quot;</code>.</p><h2 id="purchasing-the-certificate" tabindex="-1">Purchasing the certificate <a class="header-anchor" href="#purchasing-the-certificate" aria-label="Permalink to &quot;Purchasing the certificate&quot;">​</a></h2><p>On the CA website, choose a domain-validated (DV) or organization-validated (OV) certificate for one domain, and paste the content of the <em>.csr</em> file when asked:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iochembd$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iochembd.university.edu.csr</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-----BEGIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CERTIFICATE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> REQUEST-----</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-----END</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> CERTIFICATE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> REQUEST-----</span></span></code></pre></div><p>Choose <em>Apache</em>, <em>Nginx</em> or <em>Other</em> as the server type if asked: you need the certificate in PEM format.</p><h3 id="validating-domain-ownership" tabindex="-1">Validating domain ownership <a class="header-anchor" href="#validating-domain-ownership" aria-label="Permalink to &quot;Validating domain ownership&quot;">​</a></h3><p>Before issuing the certificate, the CA checks that you control the domain. See <a href="./validate-domain-owner.html">Validate the domain ownership</a>.</p><h2 id="installing-the-certificate" tabindex="-1">Installing the certificate <a class="header-anchor" href="#installing-the-certificate" aria-label="Permalink to &quot;Installing the certificate&quot;">​</a></h2><p>The CA sends the certificate and its CA chain (the intermediate certificates), usually as a ZIP file. Copy them next to the key and install them as described in <a href="./with-existing-certificate.html#update-process">Use a certificate you already own</a>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iochembd$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BASE_PATH/bin/replace-certificate.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> provided</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/certificate/iochembd_university_edu.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">              ~/certificate/iochembd.university.edu.key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/certificate/iochembd_university_edu.ca-bundle</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iochembd$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> BASE_PATH/bin/iochembd.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span></code></pre></div>`,15)]))}const F=e(n,[["render",h]]);export{k as __pageData,F as default};
